import{verifyMobileDictationFitRelease,readBeforeMobileDictationFit}from'./check-mobile-dictation-fit-release-20261101.mjs';
import assert from'node:assert/strict';import{readFileSync}from'node:fs';import{execFileSync}from'node:child_process';import{createHash}from'node:crypto';
const base='0fd8d6dc609cdfcce195063075bd64f8f0e8685e',live='f828bb6200f54a8a061f55d3a4123640c202a836',folder='docs/pace-toolbar-20261101/';
const git=(...a)=>execFileSync('git',a,{maxBuffer:128e6}),sha=b=>createHash('sha256').update(b).digest('hex'),sort=a=>a.sort((a,b)=>a.localeCompare(b)),lines=b=>b.toString().trim().split('\n').filter(Boolean);
const roots=['app','components','hooks','data','lib','public','scripts','db','drizzle','.github','AGENTS.md','PUBLICATIE.md','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','docs/KLINK-DOCENTHANDLEIDING.md','vite.config.ts','next.config.ts','package.json','package-lock.json','wrangler.jsonc'];
export function verifyPaceToolbarRelease(read=readFileSync){
 const successor=verifyMobileDictationFitRelease(read),currentRead=read;read=file=>readBeforeMobileDictationFit(file,successor,currentRead);
 const r=JSON.parse(read('docs/klink-owner-release-pace-toolbar-20261101.json'));assert.equal(r.approvedBy,'Nico');assert.equal(r.publicationApproved,true);assert.equal(r.appearanceChangeApproved,true);assert.equal(r.baselineSourceCommit,base);assert.equal(r.liveSourceCommit,live);assert(r.userRequest.includes('ruimte tussen')&&r.userRequest.includes('naast die audio'));
 git('merge-base','--is-ancestor',live,base);git('merge-base','--is-ancestor',base,'HEAD');
 const changed=sort(lines(git('diff','--name-only',base,successor.baselineSourceCommit,'--',...roots)));assert.deepEqual(changed,sort([...r.changedFiles,'docs/appearance-floor-20261031/floor.json',r.approval]));assert.deepEqual(sort(Object.keys(r.files)),r.changedFiles);for(const f of r.changedFiles)assert.equal(sha(read(f)),r.files[f],f);
 assert.equal(git('diff','--name-only',base,successor.baselineSourceCommit,'--','hooks','data','lib','public','db','drizzle','.github','package.json','package-lock.json','wrangler.jsonc').length,0,'No content, audio, progress, routes, workflows or dependency changes');
 const old=file=>git('show',base+':'+file).toString(),actual=read('app/learner-layout.css').toString();assert(actual.startsWith(old('app/learner-layout.css')));const delta=actual.slice(old('app/learner-layout.css').length);assert.equal(sha(Buffer.from(delta)),r.cssDeltaSha256);assert(delta.includes('gap: 12px')&&delta.includes('cp-pace-controls'));assert(!delta.includes('font-size')&&!delta.includes('display: none'));
 assert.equal(read('components/product/exercise-listen.tsx').toString(),old('components/product/exercise-listen.tsx').replace('ExerciseAudioSlot()','ExerciseAudioSlot({ children }: { children?: ReactNode })').replace('/><ExerciseViewPanel','/>{children}<ExerciseViewPanel'));
 assert.equal(read('components/product/package-exercise-browser.tsx').toString(),old('components/product/package-exercise-browser.tsx').replace('            <ExerciseAudioSlot />\n            {pacedReading','            <ExerciseAudioSlot>\n              {pacedReading').replace('</button>)}</fieldset>}\n','</button>)}</fieldset>}\n            </ExerciseAudioSlot>\n'));
 const floor=JSON.parse(read('docs/appearance-floor-20261031/floor.json')),previous=JSON.parse(old('docs/appearance-floor-20261031/floor.json'));assert.deepEqual({...floor,approvedUpdates:previous.approvedUpdates},previous);assert.deepEqual(floor.approvedUpdates,[...previous.approvedUpdates,r.approval]);const approval=JSON.parse(read(r.approval));assert.equal(approval.userRequest,r.userRequest);assert.deepEqual(approval.files,r.files);
 const browser=JSON.parse(read(folder+'checks.json'));assert.equal(browser.checks.length,80);assert.equal(browser.native.length,2);assert.deepEqual(browser.errors,[]);for(const c of browser.checks){assert(c.audioPaceGap>=11.5&&c.paceGaps.every(x=>x>=11.5));for(const k of['samePaceRow','desktopOneRow','allTargets48','panelSeparate','allControlsVisible','noHorizontalScroll','oldProgressPreserved'])assert.equal(c[k],true,k);}for(const c of browser.native)for(const k of['nativePlayback','space','enter','arrows','inputTyping','touch','progressPreserved'])assert.equal(c[k],true,k);
 const review=JSON.parse(read(folder+'review.json'));for(const k of['contentPreserved','audioPreserved','progressPreserved','keyboard','mobile','photoRegression','reactReview','localOnly'])assert.equal(review[k],true,k);
 const backup=JSON.parse(read(folder+'backup.json'));assert(backup.verified&&backup.fullReadback&&backup.zipIntegrity&&backup.driveId);assert.deepEqual(backup.files,r.files);return {...r,successor};
}
export function readBeforePaceToolbar(file,r,read=readFileSync){return r.changedFiles.includes(file)||file==='docs/appearance-floor-20261031/floor.json'?git('show',base+':'+file):readBeforeMobileDictationFit(file,r.successor,read);}
